// ================= Ek C: parametre azaltma (research_v4)
function FIGPNG(file, widthPx, caption) {
  const buf = fs.readFileSync(file); const pw = buf.readUInt32BE(16), ph = buf.readUInt32BE(20); const w = widthPx, h = Math.round(widthPx * ph / pw);
  return [new Paragraph({ children: [new ImageRun({ type: 'png', data: buf, transformation: { width: w, height: h }, altText: { title: file, description: caption, name: file } })], alignment: AlignmentType.CENTER, spacing: { before: 100, after: 0 }, keepNext: true }), CAP(caption)];
}
